mapdata=dict(version=1,target_profile=dict(system_boundary='Captured go.etcd.io/raft implementation. RawNode is thread-unsafe and delegates stable storage, message transport and state-machine application through Ready. Node exposes a channel API whose loop is not yet read.',protocol_contexts=['Per-node term, vote, role, leader, log and replication tracker'],external_interfaces=['RawNode.Propose, Campaign, Step, Ready, ApplyConfChange','Node.Ready/Advance and proposal retry contract'],ownership=['RawNode caller serializes calls and performs storage/network/application work.','raft owns protocol state and local completion interpretation.'],variants=['Synchronous Ready/Advance','AsyncStorageWrites local append/apply messages'],source_ids=['S_raw_entry','S_ready_contract','S_step'],unknowns=core_gaps),behaviors=behaviors,facts=[fact],surfaces=[dict(entry_point='raft.maybeCommit',disposition='deferred',reason='Calls raftLog.maybeCommit with current term and tracker.Committed. Both callees and the support aggregation caller remain unread.',source_ids=['S_reset_append'],high_consequence=True),dict(entry_point='RawNode.ApplyConfChange / Node.ApplyConfChange',disposition='deferred',reason='Application applies committed configuration changes and records returned ConfState in snapshots. In-repository configuration implementation remains unread, not externalized.',source_ids=['S_raw_entry','S_ready_contract'],high_consequence=True),dict(entry_point='RawNode.Ready / Node.Advance',disposition='deferred',reason='Ready constructs append/apply work; acceptReady and Advance execution and Node serialization loop remain unread.',source_ids=['S_raw_entry','S_ready_contract'],high_consequence=True)],core_overview=dict(status='incomplete',formation=dict(explanation='RawNode.Propose enters raft.Step with MsgProp. The read appendEntry helper stamps entries with current term and consecutive indexes, appends them and sends a deferred self MsgAppResp. maybeCommit asks the tracker for a committed index and passes it with current term to the log. Ready exposes storage, messages and committed application work; Node.Propose explicitly permits dropped proposals and assigns retry responsibility to the caller. Admission, remote support aggregation and downstream log validation are gaps, not inferred guarantees.',behavior_ids=['B_role_reset','B_append_response_packaging'],source_ids=['S_raw_entry','S_ready_contract','S_reset_append','S_send']),context=dict(explanation='Step compares message and node terms before dispatch, with explicit pre-vote and lease exceptions. Role transitions reset vote/progress/read context differently: candidacy raises term, pre-candidacy does not, and leadership appends an empty entry. Stale ordinary messages return without state-specific dispatch. Full election tally, transfer and timers remain unread.',behavior_ids=['B_step_context_and_storage','B_role_reset'],source_ids=['S_step','S_roles','S_reset_append']),connection=dict(explanation='Support emission waits behind storage completion via msgsAfterAppend, while append stabilization carries both the current protocol term and the last entry identity. Step excludes stale-term entry stabilization but still consumes snapshot completion on that branch. Apply completion messages carry zero term because their entries are already committed. This observed split connects authority changes to pending persistence and application work, but does not yet establish complete history safety.',behavior_ids=['B_append_response_packaging','B_step_context_and_storage'],fact_ids=['F_append_completion_descriptor'],source_ids=['S_send','S_append_messages','S_step']),open_details=['Lease-based versus safe ReadIndex behavior and ForgetLeader implications.'],core_gaps=core_gaps,rationale='Initial sourced partial map. Both core lines have concrete anchors but unread formation, transition and recovery responsibilities prevent usable status.'))
